-- Seed for the stores that used to be hard-coded in kora_storerobbery (shared/config.lua).
-- Safe to run more than once: existing ids are left alone, so stores edited in the creator keep their changes.

CREATE TABLE IF NOT EXISTS `qbrobberies_stores` (
  `id` varchar(48) NOT NULL,
  `data` longtext NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

